static int date_valid(const char *date){if(!*date)return 1;int y,m,d;char more;if(strlen(date)!=10||sscanf(date,"%4d-%2d-%2d%c",&y,&m,&d,&more)!=3||date[4]!='-'||date[7]!='-'||y<1900||m<1||m>12)return 0;int days[]={31,28,31,30,31,30,31,31,30,31,30,31};if(y%4==0&&(y%100!=0||y%400==0))days[1]=29;return d>=1&&d<=days[m-1];}
