static void relation_display(J *record,const char *key,const char *kind,const char *idKey){J *r=d408_find(get(workStore.data,kind),str(record,idKey));char text[1200];snprintf(text,sizeof(text),"%s%s%s%s",r?str(r,"name"):"未关联",r?" [":"",r?str(r,"id"):"",r?"]":"");ss(record,key,text);}
