static void create_instance(J *template){char *options=relation_options("templates");J *draft=record_new("");relation_display(draft,"templateChoice","templates","templateId");if(template){ss(draft,"templateId",str(template,"id"));relation_display(draft,"templateChoice","templates","templateId");ss(draft,"name",str(template,"name"));}D408Field fields[]={{L"实例名称","name",0,0,0},{L"选择流程模板（按当前修订复制）","templateChoice",0,0,options},{L"说明","notes",1,3,0}};J *r=d408_form(workWindow,L"创建流程实例",draft,fields,3);if(r){relation_collect(r,"templateChoice","templateId");J *source=d408_find(get(workStore.data,"templates"),str(r,"templateId")),*instance=make_instance(source,str(r,"name"));if(!instance||!*str(r,"name"))d408_error(workWindow,"请填写名称并选择至少含一个步骤的模板。");else{ss(instance,"notes",str(r,"notes"));if(!save_record("instances",instance,"create-instance"))d408_error(workWindow,workStore.error);}cJSON_Delete(instance);cJSON_Delete(r);}cJSON_Delete(draft);free(options);work_refresh();}
