static int instance_command(J *r,const char *action){if(!strcmp(action,"pause")&&!strcmp(str(r,"status"),"running")){ss(r,"status","paused");return 1;}if(!strcmp(action,"resume")&&!strcmp(str(r,"status"),"paused")){ss(r,"status","running");return 1;}if(strcmp(action,"advance")||strcmp(str(r,"status"),"running"))return 0;int index=(int)num(r,"currentStep");J *step=cJSON_GetArrayItem(get(r,"steps"),index);if(!step)return 0;char time[40];now(time);ss(step,"status","completed");ss(step,"completedAt",time);sn(r,"currentStep",index+1);if(index+1==cJSON_GetArraySize(get(r,"steps"))){ss(r,"status","completed");ss(r,"completedAt",time);}return 1;}
